SourceCode.Declaration:
public class UPSVendPriceAdmPost extends RunBaseBatch implements BatchRetryable
{
    UPSVendPriceJournalNum journalNum;

}

Method.Source:
public static void main(Args args)
{
    UPSVendPriceAdmTrans vendPriceAdmTrans = args.record();

    if (!vendPriceAdmTrans.RecId)
    {
        throw info("@SYS27671");
    }

    if (!vendPriceAdmTrans.JournalNum)
    {
        throw error("@SYS59010");
    }

    UPSVendPriceAdmTable vendPriceAdmTable = UPSVendPriceAdmTable::find(vendPriceAdmTrans.JournalNum);

    if (vendPriceAdmTable.Posted)
    {
        throw error("@SYS21497");
    }

    UPSVendPriceAdmPost vendPriceAdmPost = new UPSVendPriceAdmPost();
    vendPriceAdmPost.initJournalNum(vendPriceAdmTrans.JournalNum);
    vendPriceAdmPost.saveLast();

    if (vendPriceAdmPost.prompt())
    {
        vendPriceAdmPost.runOperation();
    }
}

public void run()
{
    UPSVendPriceAdmTable vendPriceAdmTable = UPSVendPriceAdmTable::find(journalNum, true);

    if (!vendPriceAdmTable.Posted)
    {
        ttsbegin;

        vendPriceAdmTable.Posted = NoYes::Yes;
        vendPriceAdmTable.PostedDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
        vendPriceAdmTable.update();

        ttscommit;
    }

}
